params.command:
$ErrorActionPreference='Stop'
$dir=Join-Path $env:USERPROFILE 'actions-runner-heaven-v2'
$run=Join-Path $dir 'run.cmd'
if(-not (Test-Path $run)){ throw ('missing '+$run) }
$configured=Test-Path (Join-Path $dir '.runner')
if(-not $configured){ throw ('runner not configured: '+$dir) }
$existing=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' -and $_.ExecutablePath -and $_.ExecutablePath.StartsWith($dir,[System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
if(-not $existing){
  $cmdExe=Join-Path ([Environment]::SystemDirectory) 'cmd.exe'
  Start-Process -FilePath $cmdExe -ArgumentList ('/d /c ""{0}""' -f $run) -WorkingDirectory $dir -WindowStyle Hidden | Out-Null
  Start-Sleep -Seconds 6
}
$listener=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' -and $_.ExecutablePath -and $_.ExecutablePath.StartsWith($dir,[System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
if(-not $listener){ throw 'heaven-v2 listener did not start' }
$r=Get-Content -Raw -LiteralPath (Join-Path $dir '.runner') | ConvertFrom-Json
[pscustomobject]@{started=$true;pid=$listener.ProcessId;agentId=$r.agentId;agentName=$r.agentName;runnerDirectory=$dir} | ConvertTo-Json -Compress
